package com.esn.smp.gameplay;
import com.esn.smp.data.ESNDataStore;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.scoreboard.*;
public final class ESNScoreboard{private final JavaPlugin plugin;private final ESNDataStore data;public ESNScoreboard(JavaPlugin p,ESNDataStore d){plugin=p;data=d;p.getServer().getScheduler().runTaskTimer(p,this::update,40,100);}private void update(){for(Player p:Bukkit.getOnlinePlayers())try{Scoreboard b=Bukkit.getScoreboardManager().getNewScoreboard();Objective o=b.registerNewObjective("esn","dummy",ChatColor.GOLD+""+ChatColor.BOLD+"ESN SMP");o.setDisplaySlot(DisplaySlot.SIDEBAR);o.getScore(ChatColor.GRAY+"play.esn").setScore(5);o.getScore(ChatColor.YELLOW+"Rank: "+ChatColor.WHITE+(p.isOp()?"Owner":"Member")).setScore(4);o.getScore(ChatColor.YELLOW+"Coins: "+ChatColor.WHITE+data.getBalance(p)).setScore(3);o.getScore(ChatColor.YELLOW+"Kills: "+ChatColor.WHITE+p.getStatistic(Statistic.PLAYER_KILLS)).setScore(2);o.getScore(ChatColor.YELLOW+"Online: "+ChatColor.WHITE+Bukkit.getOnlinePlayers().size()).setScore(1);p.setScoreboard(b);p.setPlayerListName(ChatColor.GOLD+"[ESN] "+ChatColor.WHITE+p.getName());}catch(Exception ignored){}}}
